CREATE TYPE "admin_entitlement_status" AS ENUM ('ACTIVE','SUSPENDED','EXPIRED','REVOKED');
CREATE TYPE "subscription_payment_status" AS ENUM ('SIMULATED_SUCCESS');
CREATE TABLE "admin_entitlements" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" UUID NOT NULL UNIQUE REFERENCES "users"("id") ON DELETE CASCADE, "status" "admin_entitlement_status" NOT NULL DEFAULT 'ACTIVE', "active_from" TIMESTAMPTZ(3) NOT NULL, "active_until" TIMESTAMPTZ(3) NOT NULL, "tournament_limit" INTEGER NOT NULL, "admin_access_ended_at" TIMESTAMPTZ(3), "manual_adjustment_metadata" JSONB, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "subscription_orders" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "pricing_plan_version_id" UUID NOT NULL REFERENCES "pricing_plan_versions"("id") ON DELETE RESTRICT, "idempotency_key" VARCHAR(255) NOT NULL UNIQUE, "duration_bundle" INTEGER NOT NULL DEFAULT 0, "tournament_bundle" INTEGER NOT NULL DEFAULT 0, "duration_months_granted" INTEGER NOT NULL, "tournament_limit_granted" INTEGER NOT NULL, "price_snapshot" JSONB NOT NULL, "total_amount_vnd" INTEGER NOT NULL, "payment_status" "subscription_payment_status" NOT NULL DEFAULT 'SIMULATED_SUCCESS', "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "subscription_orders_user_id_created_at_idx" ON "subscription_orders"("user_id","created_at");
